;БуквинBK_SM=-BK_+PL        DW BK0+SM,BK1+SM,BK2+SM,BK3+SM,BK4+SM,BK5+SM,BK6+SM        DW BK7+SM,BK8+SM		if RUSBK0     DB "Это не вы потеряли?",SOBES        DB "Не, это не моё.",END		elseBK0     DB "Did you lost this?",SOBES        DB "No.",END				endif		if RUSBK1     DB "Здоровечка вам! Меня зовут Вера.",CR        DB "А как вас величают?",SOBES        DB "Я библиотекарь. Буквин моя",CR        DB "фамилия.",HERO		elseBK1     DB "Hi there! My name is Vera",CR        DB "How I can call you?",SOBES        DB "I am a librarian. My name is",CR        DB "Bookwin.",HERO				endif		if RUS        DB "Вы не подскажете, что у вас тут",CR        DB "случилось?",SOBES        DB "Не мешайте, бабуля, учет у меня."        DB DIALOG,3		else        DB "Could you tell me what happened",CR        DB "here?",SOBES        DB "Don't bother, grandma, I have",CR		DB "the revision."        DB DIALOG,3				endif		if RUSBK2     DB "Милок, навостри уши, дело есть.",CR        DB "Задумала тут пивком побаловаться,",CR        DB "а из чего его готовят, забыла..."        DB SOBES		elseBK2     DB "Be sharp boy. I have an offer.",CR        DB "Would be good to drink some beer,",CR        DB "but I forgot how to make it..."        DB SOBES				endif		if RUS        DB "Пивко, это дело! Дай, вспомню...",CR        DB "Ага, чтобы пиво зрело, нужен мед,",CR        DB "хмель, зерна пшеницы и... время."        DB NEXT        DB "Тогда добрый напиток выйдет!",SCRPT,25		else		DB "Beer? That's great! Let me think...",CR        DB "Well, you'll need some honey,",CR        DB "hops, wheat grains and... time."        DB NEXT        DB "Then you'll get good drink!",SCRPT,25		endif		if RUSBK3     DB "Что поделываешь, милок?",SOBES        DB "Книги пересчитываю.",END		elseBK3     DB "What's up boy?",SOBES        DB "I am revisioning books.",END		; не совсем уверен, но лучше не подобрал слова... checking - странно звучит		endif		if RUSBK4     DB "Кхе-кхе... Вампиры. Слыхал",CR ;fix by Sergio        DB "о таких? Достали, окаянные. Летають,",CR;BK4     DB "Кхе-кхе... Вампиры. Слыхал о таких?",CR;        DB "Достали, окаянные. Летають,",CR         DB "пугають, вперед не пускають!",SOBES        DB "Да, гады изрядные. Помню, книжка",CR        DB "была, как ентую нечисть изводить.",CR        DB "Ух, и древняя книга...",HERO		elseBK4     DB "Hmmm... Vampires. You know...",CR        DB "They are flying, frightening,",CR        DB "blocking my way!",SOBES        DB "Yeah, I know. I am having the",CR        DB "book about them.",CR        DB "The old one...",HERO				endif		if RUS        DB "Почитать бы... Выручай, милок!",SOBES        DB "Я бы с радостью, но правило есть:",CR        DB 34,"Редкие книги на руки выдавать",CR        DB "нельзя",34,". Хотя... Вы слыхали такой"        DB NEXT        DB "научный термин, как ",34,"взятка",34,"?",SCRPT,39		else        DB "I need it... Help me boy!",SOBES        DB "With my pleasure, but I have the",CR        DB "rule: ",34,"Don't give rare books",34,".",CR        DB "But... Have you ever heard about"        DB NEXT        DB "the term ",34,"bribe",34,"?",SCRPT,39		endif 		if RUSBK5     DB "Держи, милок! Тебе бы придворным",CR        DB "чиновником служить...",SOBES        DB "Дык был, попёрли... А тут, какой",CR        DB "доход с библиотеки-та?",SCRPT,38		elseBK5     DB "Take this boy! You should work",CR        DB "clerk...",SOBES        DB "Well, I was... The library",CR        DB "brings no profit...",SCRPT,38				endif		if RUSBK6     DB "Чой-то я заплутала...",SOBES        DB "Ну вот, опять мне голову напекло!",END		elseBK6     DB "Oh... I am lost...",SOBES        DB "And again got the insolation!",END		 ;не совсем уверен с термине		endif		if RUSBK7     DB "Посторожи-ка эту штуку...",SOBES        DB "Сгиньте окаянные!",END		elseBK7     DB "Keep this thing...",SOBES        DB "Die busters!",END				endif;           123456789-123456789-123456789-123		if RUSBK8     DB "Пожалей бабку, отдай книгу.",SOBES        DB "Ты чо, бабуля, сдурела? Что щас",CR        DB "за так делается-то?!",END		elseBK8     DB "Have a pity. Give me the book.",SOBES        DB "You are crazy? Have you ever",CR        DB "seen something for free?!",END				endifBEND